function ActivationOrigin([string]$generation,[string]$token,[int]$depth=0) {
 if($depth -gt 32 -or $generation -cnotmatch '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'){throw 'owned_activation_origin_invalid'}
